SELECT FROM team WHERE workspace_id = #{workspaceId}
AND archived_at IS NULL
ORDER BY archived_at IS NOT NULL, name, id

SELECT 
FROM team
WHERE workspace_id = #{workspaceId} AND id = #{id}

SELECT 
FROM team t
WHERE t.workspace_id = #{workspaceId}
  AND (
    t.manager_user_id = #{userId}
    OR EXISTS (
      SELECT 1
      FROM team_member tm
      WHERE tm.workspace_id = t.workspace_id
        AND tm.team_id = t.id
        AND tm.user_id = #{userId}
    )
  )
ORDER BY t.workspace_id, t.id

SELECT workspace_id, team_id, user_id, role, created_at
FROM team_member
WHERE workspace_id = #{workspaceId}
  AND team_id IN

    #{teamId}

ORDER BY team_id, role = 'manager' DESC, user_id

SELECT EXISTS(
  SELECT 1
  FROM team_member
  WHERE workspace_id = #{workspaceId} AND team_id = #{teamId} AND user_id = #{userId}
)

